-- Base propia de Cresova (Postgres en el VPS). Mismas tablas y columnas que la base de cresova.com
-- (Lovable Cloud) para que la copia sea 1 a 1; los enums de allá se guardan como texto.
-- Se aplica sola al arrancar la oficina: todo es "if not exists", nunca borra nada.
create table if not exists clients (id uuid primary key default gen_random_uuid(), name text, business_name text, service text, status text, start_date date, next_payment_date date, monthly_fee numeric default 0, payment_status text, assigned_to uuid, notes text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), payment_frequency_days integer default 30, portal_slug text, portal_pin_hash text, portal_enabled boolean default false, default_package_id uuid, auto_generate_package boolean default false, email text, phone text, rtn text, contact_name text, contact_role text, legal_rep text, legal_rep_id text, logo_url text, brand_colors jsonb, sector text, website_url text, website_project_id text, website_status text, brand_style text, reference_urls text[], demo_generated_at timestamptz, demo_prompt text, logo_path text, site_type text, source text, fecha_primer_contacto date, detalle_origen text, referido_por text, telefono_normalizado text, fecha_demo_realizada date, resultado_demo text, meta_fbp text, meta_fbc text, meta_ref text, meta_captured_at timestamptz);
create table if not exists quotes (id uuid primary key default gen_random_uuid(), quote_number text, client_name text, client_company text, client_phone text, client_email text, status text, subtotal numeric default 0, discount_type text, discount_value numeric default 0, total numeric default 0, notes text, valid_until date, public_token uuid default gen_random_uuid(), created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), sent_at timestamptz, responded_at timestamptz, client_rtn text, client_contact_name text, client_contact_role text, client_legal_rep text, client_legal_rep_id text, is_enterprise boolean default false, enterprise_data jsonb, tax_enabled boolean default false, tax_rate numeric default 15, tax_amount numeric default 0, subtotal_setup numeric default 0, subtotal_monthly numeric default 0, client_id uuid, accepted_at timestamptz, seller_id uuid, dev_assignee uuid, project_status text, project_notes text, currency text, fx_rate numeric default 1, total_hnl numeric default 0, subtotal_yearly numeric default 0, dev_brief text, dev_brief_links text[], dev_brief_files jsonb, show_ai_diagram boolean, doc_lang text, fecha_demo_realizada date, resultado_demo text, motivo_no_cierre text, tipo_venta text, paquete_resumen text, delivered_at timestamptz, meta_lead_sent_at timestamptz, meta_purchase_sent_at timestamptz, meta_last_error text, meta_attempts integer default 0, demo_url text);
create table if not exists quote_items (id uuid primary key default gen_random_uuid(), quote_id uuid, product_id uuid, name text, description text, unit_price numeric default 0, quantity numeric default 1, subtotal numeric default 0, sort_order integer default 0, created_at timestamptz default now(), is_recommended boolean default false, billing text, list_price numeric default 0, discount_pct numeric default 0);
create table if not exists quote_payments (id uuid primary key default gen_random_uuid(), quote_id uuid, amount numeric, paid_at date, method text, reference text, notes text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), treasury_account_id uuid, client_id uuid, payer_name text, source text, external_ref text);
create table if not exists quote_products (id uuid primary key default gen_random_uuid(), name text, description text, base_price numeric default 0, kind text, sort_order integer default 0, is_active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now(), eur_price numeric, name_pt text, description_pt text);
create table if not exists tasks (id uuid primary key default gen_random_uuid(), title text, notes text, assigned_to uuid, created_by uuid, client_id uuid, quote_id uuid, category text, status text, priority text, due_date date, estimated_minutes integer, actual_minutes integer default 0, focus_started_at timestamptz, focus_minutes integer, completed_at timestamptz, source text, auto_key text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists expenses (id uuid primary key default gen_random_uuid(), expense_date date, amount numeric, currency text, vendor text, description text, category_id uuid, expense_type text, status text, payment_method text, account_id uuid, paid_at date, client_id uuid, quote_id uuid, receipt_url text, receipt_path text, notes text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), external_ref text, source text, fx_rate numeric default 1, amount_hnl numeric);
create table if not exists expense_categories (id uuid primary key default gen_random_uuid(), key text, label text, is_active boolean default true, sort_order integer default 0, created_at timestamptz default now());
create table if not exists treasury_accounts (id uuid primary key default gen_random_uuid(), name text, holder text, type text, is_active boolean default true, description text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists treasury_transfers (id uuid primary key default gen_random_uuid(), transfer_date date, from_account_id uuid, to_account_id uuid, amount numeric, reference text, receipt_url text, notes text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists fixed_costs (id uuid primary key default gen_random_uuid(), name text, amount numeric default 0, currency text, frequency text, category_id uuid, vendor text, due_day integer, account_id uuid, is_active boolean default true, notes text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists payroll_payments (id uuid primary key default gen_random_uuid(), seller_id uuid, period_month date, base_amount numeric default 0, commission_amount numeric default 0, total_amount numeric, paid_at date, treasury_account_id uuid, method text, notes text, expense_id uuid, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists sellers (id uuid primary key default gen_random_uuid(), user_id uuid, display_name text, base_salary numeric default 0, commission_setup_pct numeric default 0.20, commission_recurring_pct numeric default 0.20, is_active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists contracts (id uuid primary key default gen_random_uuid(), contract_number text, quote_id uuid, client_id uuid, template_id uuid, title text, client_name text, client_company text, client_email text, client_phone text, body text, clauses jsonb, total numeric default 0, currency text, status text, public_token uuid default gen_random_uuid(), sent_at timestamptz, viewed_at timestamptz, signed_at timestamptz, rejected_at timestamptz, signature_data_url text, signature_name text, signature_ip text, signature_user_agent text, rejection_reason text, pdf_path text, notes text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), metadata jsonb, client_rtn text, client_contact_name text, client_contact_role text, client_legal_rep text, client_legal_rep_id text, rendered_body text);
create table if not exists contract_templates (id uuid primary key default gen_random_uuid(), name text, description text, body text, default_clause_ids uuid[], is_active boolean default true, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists contract_clauses (id uuid primary key default gen_random_uuid(), title text, category text, body text, is_default boolean default false, is_active boolean default true, position integer default 0, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists contract_events (id uuid primary key default gen_random_uuid(), contract_id uuid, event_type text, metadata jsonb, ip text, user_agent text, actor_user_id uuid, created_at timestamptz default now());
create table if not exists org_settings (id boolean primary key default true, prestador_nombre text, prestador_identidad text, prestador_nacionalidad text, marca_comercial text, datos_pago text, telefono_contacto text, email_contacto text, jurisdiccion text, created_at timestamptz default now(), updated_at timestamptz default now(), prestador_rtn text, representante_legal_nombre text, representante_legal_identidad text, datos_pago_personal text, costo_por_venta_maximo numeric default 2500, tasa_cierre_demos_manual numeric default 0.33, ventas_punto_equilibrio integer default 5);
create table if not exists profiles (id uuid primary key, full_name text, created_at timestamptz default now(), preferred_locale text, preferred_currency text);
create table if not exists meta_ad_reports (id uuid primary key default gen_random_uuid(), semana_inicio date, gasto_hnl numeric default 0, conversaciones_iniciadas integer default 0, notas text, created_at timestamptz default now(), updated_at timestamptz default now());

create unique index if not exists quotes_numero on quotes (quote_number);
create index if not exists quotes_estado on quotes (status, project_status);
create index if not exists items_quote on quote_items (quote_id);
create index if not exists pagos_quote on quote_payments (quote_id);
create unique index if not exists gastos_ref on expenses (external_ref) where external_ref is not null;
create index if not exists gastos_fecha on expenses (expense_date);
create index if not exists tareas_quote on tasks (quote_id);

-- Qué se copió de cresova.com y cuándo.
create table if not exists _sincronizacion (tabla text primary key, filas integer, ts timestamptz default now());

-- Renovaciones de hosting y dominio (propia de la oficina, 6 nov 2026).
create table if not exists renovaciones (quote_id uuid primary key, cliente text, telefono text, dominio text, vence date, estimado boolean default true, precio numeric, estado text default 'pendiente', avisado_cliente_at timestamptz, notas text, created_at timestamptz default now(), updated_at timestamptz default now());
